fn choose(start: usize, values: &[i32], path: &mut Vec<i32>, out: &mut Vec<Vec<i32>>) {
    out.push(path.clone());
    for index in start..values.len() {
        path.push(values[index]);
        choose(index + 1, values, path, out);
        path.pop();
    }
}

